import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Features card 2 – static sprite with an engineered gradient surface.
 * Renders a billboard plane facing the camera, textured from the atlas region.
 */
export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Aspect ratio from atlas source rect (512×320)
  const aspect = 512 / 320;
  const width = 2;
  const height = width / aspect;

  // Plane geometry – will be oriented toward camera once
  const geometry = new ctx.THREE.PlaneGeometry(width, height);

  // Material – will receive the loaded texture
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: false, // sprite-like transparency handling
  });

  const mesh = new ctx.THREE.Mesh(geometry, material);

  // Orient to face camera (static billboard)
  // Camera is at (0,0,10) by default; we look from the mesh position towards it
  mesh.position.set(0, 0, 0);
  mesh.lookAt(0, 0, 10);

  group.add(mesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      // Apply texture with no offset – the image is already the atlas region
      material.map = texture;
      material.needsUpdate = true;
    });
  }

  // No event handlers for this static element
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) {
      material.map.dispose();
    }
  };

  return group;
}
